-- Ventaari Brightwish (251487): Russian translation of the three existing gossip responses.
-- Project translation of the enUS official-beta capture in 2026_10_01_02_hotfixes_forever_sniff.sql.
-- Not an official Russian capture. Compatible with 70938; VerifiedBuild=0 marks custom locale data.
-- Preserve all original text, gameplay fields and existing nonempty Russian translations.
SET NAMES utf8mb4;
START TRANSACTION;
INSERT INTO broadcast_text_locale (ID,locale,Text_lang,Text1_lang,VerifiedBuild) SELECT 304012,'ruRU','','Чем я могу помочь тебе, $Gваятель:ваятельница; ветра?',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM broadcast_text_locale WHERE ID=304012 AND locale='ruRU');
UPDATE broadcast_text_locale SET Text1_lang='Чем я могу помочь тебе, $Gваятель:ваятельница; ветра?' WHERE ID=304012 AND locale='ruRU' AND COALESCE(Text1_lang,'')='';
INSERT INTO hotfix_data (Id,UniqueId,TableHash,RecordId,Status,VerifiedBuild) VALUES (4050003,1,35137211,304012,1,0) ON DUPLICATE KEY UPDATE Status=VALUES(Status);
INSERT INTO broadcast_text_locale (ID,locale,Text_lang,Text1_lang,VerifiedBuild) SELECT 305036,'ruRU','','К сожалению, Зефрис приходит в упадок. Духи ветра, которые привели нас сюда, в Небесную высь, много тысяч лет назад, исчезли. Вместе с ними мы лишились значительной части магии, от которой зависели на протяжении тысячелетий.\r\n\r\nСам остров тоже стал опасно нестабилен. Мы даже потеряли связь с другими островными владениями шен''дорай. Немногие Ваятели ветра, ещё наделённые небесным взором, пытались связаться с нашими братьями и сёстрами на других островах, но ответа не получили.\r\n\r\nМногие из нас опасаются, что шен''дорай Зефриса — всё, что осталось от нашего народа.',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM broadcast_text_locale WHERE ID=305036 AND locale='ruRU');
UPDATE broadcast_text_locale SET Text1_lang='К сожалению, Зефрис приходит в упадок. Духи ветра, которые привели нас сюда, в Небесную высь, много тысяч лет назад, исчезли. Вместе с ними мы лишились значительной части магии, от которой зависели на протяжении тысячелетий.\r\n\r\nСам остров тоже стал опасно нестабилен. Мы даже потеряли связь с другими островными владениями шен''дорай. Немногие Ваятели ветра, ещё наделённые небесным взором, пытались связаться с нашими братьями и сёстрами на других островах, но ответа не получили.\r\n\r\nМногие из нас опасаются, что шен''дорай Зефриса — всё, что осталось от нашего народа.' WHERE ID=305036 AND locale='ruRU' AND COALESCE(Text1_lang,'')='';
INSERT INTO hotfix_data (Id,UniqueId,TableHash,RecordId,Status,VerifiedBuild) VALUES (4050003,2,35137211,305036,1,0) ON DUPLICATE KEY UPDATE Status=VALUES(Status);
INSERT INTO broadcast_text_locale (ID,locale,Text_lang,Text1_lang,VerifiedBuild) SELECT 305038,'ruRU','','Шен''дорай всегда будут в долгу перед духами за их помощь. Ваятели ветра поклялись вернуть этот долг и восстановить прежний порядок. К сожалению, без духов, которые направляли нас, мы почти не знаем, что происходит вокруг в Небесной выси. И это опасно.\r\n\r\nЧлены Высшего ордена близоруки и высокомерны, совсем как их предки-высокорождённые. Они стремятся овладеть магией этого места и подчинить её себе. Но именно этот путь когда-то заставил нас бежать из Калимдора и поселиться здесь. Боюсь, что, как и у наших предков, их самоуверенность намного превосходит их умения, а последствия могут оказаться катастрофическими.',0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM broadcast_text_locale WHERE ID=305038 AND locale='ruRU');
UPDATE broadcast_text_locale SET Text1_lang='Шен''дорай всегда будут в долгу перед духами за их помощь. Ваятели ветра поклялись вернуть этот долг и восстановить прежний порядок. К сожалению, без духов, которые направляли нас, мы почти не знаем, что происходит вокруг в Небесной выси. И это опасно.\r\n\r\nЧлены Высшего ордена близоруки и высокомерны, совсем как их предки-высокорождённые. Они стремятся овладеть магией этого места и подчинить её себе. Но именно этот путь когда-то заставил нас бежать из Калимдора и поселиться здесь. Боюсь, что, как и у наших предков, их самоуверенность намного превосходит их умения, а последствия могут оказаться катастрофическими.' WHERE ID=305038 AND locale='ruRU' AND COALESCE(Text1_lang,'')='';
INSERT INTO hotfix_data (Id,UniqueId,TableHash,RecordId,Status,VerifiedBuild) VALUES (4050003,3,35137211,305038,1,0) ON DUPLICATE KEY UPDATE Status=VALUES(Status);
COMMIT;
